/// A payload whose layout the record's EditorID prefix selects (union). A payload no
/// variant claims is kept raw in the record's `extra`.
#[derive(Debug, Clone, PartialEq)]
pub enum GmstValue {
    /// EditorID starting with `b`.
    Bool(u32),
    /// EditorID starting with `f`.
    Float(f32),
    /// EditorID starting with `i`.
    Int(i32),
    /// EditorID starting with `s`.
    String(LString),
    /// EditorID starting with `u`.
    Unsigned(u32),
}

impl GmstValue {
    /// The EditorID prefix byte that selects this variant.
    pub fn prefix(&self) -> u8 {
        match self {
            Self::Bool(_) => b'b',
            Self::Float(_) => b'f',
            Self::Int(_) => b'i',
            Self::String(_) => b's',
            Self::Unsigned(_) => b'u',
        }
    }
}

impl ByPrefix for GmstValue {
    fn read_for(
        prefix: u8,
        r: &mut Reader<'_>,
        field: &'static str,
        ctx: Ctx,
    ) -> Result<Self, DecodeError> {
        match prefix {
            b'b' => Field::read(r, field, ctx).map(Self::Bool),
            b'f' => Field::read(r, field, ctx).map(Self::Float),
            b'i' => Field::read(r, field, ctx).map(Self::Int),
            b's' => Field::read(r, field, ctx).map(Self::String),
            b'u' => Field::read(r, field, ctx).map(Self::Unsigned),
            _ => Err(DecodeError::Undecided { field }),
        }
    }
}

impl Field for GmstValue {
    /// Unions are read with [`ByPrefix::read_for`]; without the decider there is no layout.
    fn read(_r: &mut Reader<'_>, field: &'static str, _ctx: Ctx) -> Result<Self, DecodeError> {
        Err(DecodeError::Undecided { field })
    }

    fn write(&self, out: &mut Vec<u8>) {
        match self {
            Self::Bool(value) => value.write(out),
            Self::Float(value) => value.write(out),
            Self::Int(value) => value.write(out),
            Self::String(value) => value.write(out),
            Self::Unsigned(value) => value.write(out),
        }
    }
}

impl Visit for GmstValue {
    fn visit_lstrings<'a>(&'a self, path: &'static str, out: &mut LStrings<'a>) {
        if let Self::String(value) = self {
            visit_lstrings(value, path, out);
        }
    }

    fn visit_lstrings_mut<'a>(&'a mut self, path: &'static str, out: &mut LStringsMut<'a>) {
        if let Self::String(value) = self {
            visit_lstrings_mut(value, path, out);
        }
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct GmstRecord {
    /// `EDID`, required.
    pub editor_id: Option<Sub<ZString>>,
    /// `XALG`, optional.
    pub xalg: Option<Sub<Bytes>>,
    /// `DATA`, required.
    pub value: Option<Sub<GmstValue>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl GmstRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"XALG",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Required,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "GMST.EDID", ctx, extra)
                }
                Hit::Sub { member: 1, index } => {
                    put(&mut self.xalg, subs, *index, "GMST.XALG", ctx, extra)
                }
                Hit::Sub { member: 2, index } => {
                    put_by_prefix(&mut self.value, subs, *index, "GMST.DATA", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        emit(out, *b"XALG", self.xalg.as_ref());
        emit(out, *b"DATA", self.value.as_ref());
    }
}

impl Visit for GmstRecord {
    fn visit_lstrings<'a>(&'a self, _path: &'static str, out: &mut LStrings<'a>) {
        visit_lstrings(&self.value, "GMST.DATA", out);
    }

    fn visit_lstrings_mut<'a>(&'a mut self, _path: &'static str, out: &mut LStringsMut<'a>) {
        visit_lstrings_mut(&mut self.value, "GMST.DATA", out);
    }
}

impl GmstRecord {
    /// Record signature.
    pub const SIGNATURE: Sig = *b"GMST";

    /// Decodes a record body. Never fails: subrecords that match no member or do not
    /// decode are kept in `extra`.
    pub fn decode(subs: &[RawSub<'_>], ctx: Ctx) -> Self {
        let (hits, unmatched_indexes) = match_members(subs, Self::MEMBERS);
        let mut record = Self::default();
        let mut extra = Vec::new();
        for index in unmatched_indexes {
            if let Some(sub) = subs.get(index) {
                extra.push((index, OwnedSub::from(sub)));
            }
        }
        record.fill(&hits, subs, ctx, &mut extra);
        record.extra = extra;
        record
    }

    /// Encodes the record body: typed members in definition order, `extra` re-inserted at
    /// the indexes it was read from.
    pub fn encode(&self) -> Vec<OwnedSub> {
        let mut out = Vec::new();
        self.emit(&mut out);
        merge_extra(out, &self.extra)
    }

    /// Every FormID-typed value (raw, as stored), in definition order, with the path of
    /// the member or field holding it. `extra` and opaque payloads are not visited.
    pub fn form_ids(&self) -> FormIds<'_> {
        let mut out = Vec::new();
        self.visit_form_ids("GMST", &mut out);
        out
    }

    /// [`Self::form_ids`], mutably (for remapping FormIDs in place).
    pub fn form_ids_mut(&mut self) -> FormIdsMut<'_> {
        let mut out = Vec::new();
        self.visit_form_ids_mut("GMST", &mut out);
        out
    }

    /// Every lstring value, in definition order, with the path of the member or field
    /// holding it. `extra` and opaque payloads are not visited.
    pub fn lstrings(&self) -> LStrings<'_> {
        let mut out = Vec::new();
        self.visit_lstrings("GMST", &mut out);
        out
    }

    /// [`Self::lstrings`], mutably (for replacing string IDs with inline text).
    pub fn lstrings_mut(&mut self) -> LStringsMut<'_> {
        let mut out = Vec::new();
        self.visit_lstrings_mut("GMST", &mut out);
        out
    }
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct KywdRecord {
    /// `EDID`, optional.
    pub editor_id: Option<Sub<ZString>>,
    /// Group `BfcbBlock`, repeated.
    pub bfcb_block: Vec<BfcbBlock>,
    /// `CNAM`, required.
    pub cnam: Option<Sub<Bytes>>,
    /// `DNAM`, optional.
    pub dnam: Option<Sub<Bytes>>,
    /// `TNAM`, required.
    pub tnam: Option<Sub<Bytes>>,
    /// `FNAM`, required.
    pub fnam: Option<Sub<Bytes>>,
    /// `DATA`, optional.
    pub data: Option<Sub<Bytes>>,
    /// `ENAM`, optional.
    pub enam: Option<Sub<Bytes>>,
    /// `FULL`, optional.
    pub name: Option<Sub<LString>>,
    /// Subrecords that matched no member or failed to decode, each with its index
    /// in the record body as read. `encode` re-inserts them at those indexes (see
    /// `merge_extra`); when typed values are added or removed, an index stays a number,
    /// so the entry may land next to different neighbours.
    pub extra: Vec<(usize, OwnedSub)>,
}

impl KywdRecord {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"EDID",
            card: Card::Optional,
        },
        MemberDesc::Group {
            card: Card::Repeated,
            members: BfcbBlock::MEMBERS,
        },
        MemberDesc::Sub {
            sig: *b"CNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DNAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"TNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"FNAM",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"ENAM",
            card: Card::Optional,
        },
        MemberDesc::Sub {
            sig: *b"FULL",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => {
                    put(&mut self.editor_id, subs, *index, "KYWD.EDID", ctx, extra)
                }
                Hit::Group { member: 1, hits } => {
                    let mut group = BfcbBlock::default();
                    group.fill(hits, subs, ctx, extra);
                    self.bfcb_block.push(group);
                }
                Hit::Sub { member: 2, index } => {
                    put(&mut self.cnam, subs, *index, "KYWD.CNAM", ctx, extra)
                }
                Hit::Sub { member: 3, index } => {
                    put(&mut self.dnam, subs, *index, "KYWD.DNAM", ctx, extra)
                }
                Hit::Sub { member: 4, index } => {
                    put(&mut self.tnam, subs, *index, "KYWD.TNAM", ctx, extra)
                }
                Hit::Sub { member: 5, index } => {
                    put(&mut self.fnam, subs, *index, "KYWD.FNAM", ctx, extra)
                }
                Hit::Sub { member: 6, index } => {
                    put(&mut self.data, subs, *index, "KYWD.DATA", ctx, extra)
                }
                Hit::Sub { member: 7, index } => {
                    put(&mut self.enam, subs, *index, "KYWD.ENAM", ctx, extra)
                }
                Hit::Sub { member: 8, index } => {
                    put(&mut self.name, subs, *index, "KYWD.FULL", ctx, extra)
                }
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"EDID", self.editor_id.as_ref());
        for group in &self.bfcb_block {
            group.emit(out);
        }
        emit(out, *b"CNAM", self.cnam.as_ref());
        emit(out, *b"DNAM", self.dnam.as_ref());
        emit(out, *b"TNAM", self.tnam.as_ref());
        emit(out, *b"FNAM", self.fnam.as_ref());
        emit(out, *b"DATA", self.data.as_ref());
        emit(out, *b"ENAM", self.enam.as_ref());
        emit(out, *b"FULL", self.name.as_ref());
    }
}

