#[derive(Debug, Clone, PartialEq)]
pub struct Tes4Header {
    pub version: f32,
    pub record_count: u32,
    pub next_object_id: u32,
}

impl Field for Tes4Header {
    fn read(r: &mut Reader<'_>, _field: &'static str, ctx: Ctx) -> Result<Self, DecodeError> {
        let f0 = f32::read(r, "TES4.HEDR.Version", ctx)?;
        let f1 = u32::read(r, "TES4.HEDR.RecordCount", ctx)?;
        let f2 = u32::read(r, "TES4.HEDR.NextObjectId", ctx)?;
        Ok(Self {
            version: f0,
            record_count: f1,
            next_object_id: f2,
        })
    }

    fn write(&self, out: &mut Vec<u8>) {
        self.version.write(out);
        self.record_count.write(out);
        self.next_object_id.write(out);
    }
}

