#[derive(Debug, Clone, PartialEq, Default)]
pub struct Tes4Master {
    /// `MAST`, required.
    pub file_name: Option<Sub<ZString>>,
    /// `DATA`, optional.
    pub file_size: Option<Sub<u64>>,
}

impl Tes4Master {
    /// Members in on-disk order.
    pub const MEMBERS: &'static [MemberDesc] = &[
        MemberDesc::Sub {
            sig: *b"MAST",
            card: Card::Required,
        },
        MemberDesc::Sub {
            sig: *b"DATA",
            card: Card::Optional,
        },
    ];

    fn fill(
        &mut self,
        hits: &[Hit],
        subs: &[RawSub<'_>],
        ctx: Ctx,
        extra: &mut Vec<(usize, OwnedSub)>,
    ) {
        for hit in hits {
            match hit {
                Hit::Sub { member: 0, index } => put(
                    &mut self.file_name,
                    subs,
                    *index,
                    "TES4.Master.MAST",
                    ctx,
                    extra,
                ),
                Hit::Sub { member: 1, index } => put(
                    &mut self.file_size,
                    subs,
                    *index,
                    "TES4.Master.DATA",
                    ctx,
                    extra,
                ),
                _ => unmatched(hit, subs, extra),
            }
        }
    }

    fn emit(&self, out: &mut Vec<OwnedSub>) {
        emit(out, *b"MAST", self.file_name.as_ref());
        emit(out, *b"DATA", self.file_size.as_ref());
    }
}

